import React, { useState, useRef } from 'react';
import { View, TextInput } from 'react-native';

import { Entypo } from '@expo/vector-icons';
import { styles } from './styles'

import { useLoadPage } from '../../hooks/loadPage'

export function SearchNumber() {
    const ref = useRef<TextInput>(null);
    const [value, onChangeText] = useState<string>('Buscar');

    const { LoadPage } = useLoadPage()

    function filterString(text: string) {
        if (text === text.replace(/[^0-9]/g, '')) onChangeText(text);
    }

    return (
        <View style={styles.container}>
            <TextInput
                style={styles.input}
                onChangeText={text => filterString(text)}
                value={value}
                maxLength={4}
                keyboardType='numeric'
                autoCorrect={false}
                placeholderTextColor='#fff'
                onFocus={() => {
                    ref.current?.clear();
                    onChangeText('')
                }}
                onBlur={() => {
                    if (value) LoadPage(Number(value));
                    onChangeText('Buscar');
                }}
                ref={ref}
            />
            <View>
                <Entypo
                    name="magnifying-glass"
                    size={24}
                    color="rgb(220,220,220)"
                    style={styles.button}
                />
            </View>
        </View>
    );
};
